#!/usr/bin/env python3
"""Regenerate static HTML from site/assets/games-data.json. Never changes games/thumbnails."""
import json,re,unicodedata,html,shutil
from pathlib import Path
from urllib.parse import quote
from collections import Counter
ROOT=Path(__file__).resolve().parent; OUT=ROOT/'site'; BASE='https://arcadewebsite.com'
data=json.loads((OUT/'assets/games-data.json').read_text()); games=data['games']; categories=data['categories']
def esc(v):return html.escape(str(v),quote=True)
def slug(v):return re.sub(r'[^a-z0-9]+','-',unicodedata.normalize('NFKD',v).encode('ascii','ignore').decode().lower()).strip('-') or 'game'
used=set(); counts=Counter(g['t'] for g in games)
for g in games:
 s=slug(g['t']);s=s if s not in used else s+'-'+str(g['i']);used.add(s);g['slug']=s;g['url']='/game/'+s+'/';g['image']='/thumbnails/'+quote(g['s'],safe='')+'.png';g['file']='/games/'+quote(g['f'],safe='');g['display']=g['t']+((' · Edition '+str(g['i'])) if counts[g['t']]>1 else '')
byid={g['i']:g for g in games}; caturl=lambda c:'/category/'+slug(c)+'/'
def ad(id,kind='leaderboard'):
 size={'leaderboard':'728 × 90','sidebar':'160 × 600','infeed':'300 × 250','rectangle':'300 × 250'}[kind]
 return f'<aside class="ad ad-{kind}" id="{id}" data-ad-slot="{id}" aria-label="Advertisement placeholder"><span>ADVERTISEMENT</span><small>{size} · Ad space</small></aside>'
def card(g):return f'<a class="card" href="{g["url"]}"><div class="card-image"><img src="{g["image"]}" alt="{esc(g["t"])} game thumbnail" loading="lazy" width="480" height="320"></div><div class="card-info"><h3>{esc(g["display"])}</h3><div class="card-meta"><span>{esc(g["c"])}</span><span class="free">FREE TO PLAY ↗</span></div></div></a>'
def grid(gs,slot=None):
 parts=[card(g) for g in gs]
 if slot:parts.insert(min(7,len(parts)),ad(slot,'infeed'))
 return '<div class="grid">'+''.join(parts)+'</div>'
def row(title,gs,id,subtitle='',link='/all-games/'):
 return f'<section class="section"><div class="section-head"><div><h2>{title}</h2><p>{subtitle}</p></div><div class="section-actions"><a href="{link}">View all ↗</a><button class="arrow" data-scroll="{id}" data-direction="-1" aria-label="Previous {title} games">←</button><button class="arrow" data-scroll="{id}" data-direction="1" aria-label="Next {title} games">→</button></div></div><div class="row" id="{id}">'+''.join(card(g) for g in gs)+'</div></section>'
nav=''.join(f'<a href="{caturl(c["name"])}">{esc(c["name"])}</a>' for c in categories)
header=f'<a class="skip" href="#main">Skip to content</a><header class="header"><div class="wrap topbar"><a class="brand" href="/" aria-label="ArcadeWebsite home"><span class="brand-icon">A<span aria-hidden="true">↗</span></span>ARCADE<em>WEBSITE</em></a><nav class="mainnav" aria-label="Main"><a href="/all-games/">Discover</a><a href="/#categories">Categories</a><a href="/#featured">Featured</a></nav><form class="search" action="/search/" role="search"><input type="search" name="q" placeholder="Find your next game…" aria-label="Search games" required><button aria-label="Submit search">⌕</button></form></div></header><nav class="wrap catnav" aria-label="Game categories"><a href="/all-games/">ALL GAMES</a>{nav}</nav>'
footer='<footer><div class="wrap"><div class="footer-top"><div><a class="brand" href="/">ARCADE<em>WEBSITE</em></a><p>Your next great game is a click away. Discover free arcade experiences, revisit classics, and find a new favorite.</p></div><nav class="footer-links" aria-label="Footer"><a href="/all-games/">All games</a><a href="/#categories">Categories</a><a href="/search/">Find a game</a><a href="/sitemap.xml">Sitemap</a></nav></div><div class="footer-bottom"><span>ArcadeWebsite.com · Free to explore. Built for play.</span><span>Games and trademarks belong to their respective owners.</span></div></div></footer>'
urls=[]
def page(path,title,desc,body,schemas=None,image='/assets/og-image.png',noindex=False):
 canonical=BASE+path; meta=f'<title>{esc(title)}</title><meta name="description" content="{esc(desc)}"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(desc)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{BASE+image}"><meta property="og:site_name" content="ArcadeWebsite"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{esc(title)}"><meta name="twitter:description" content="{esc(desc)}"><meta name="twitter:image" content="{BASE+image}">'
 if noindex:meta+='<meta name="robots" content="noindex,follow">'
 structured=''.join('<script type="application/ld+json">'+json.dumps(s,ensure_ascii=False).replace('<','\\u003c')+'</script>' for s in schemas or [])
 doc='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">'+meta+'<meta name="theme-color" content="#0c0e13"><link rel="icon" href="/favicon.svg"><link rel="stylesheet" href="/assets/style.css">'+structured+'<script defer src="/assets/analytics.js"></script><script defer src="/assets/app.js"></script><script defer src="/assets/ads.js"></script></head><body>'+header+'<main class="wrap" id="main">'+body+'</main>'+footer+'</body></html>'
 dest=OUT/path.strip('/')/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(doc)
 if not noindex:urls.append(canonical)
def crumbs(items):
 return {'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':i+1,'name':n,'item':BASE+u} for i,(n,u) in enumerate(items)]}
catintro={'Arcade':'Quick sessions, unusual challenges, and familiar favorites: explore our broadest collection of free browser games.','Platformer':'Jump into precision challenges and side-scrolling adventures. Find your next platformer and play on its dedicated game page.','Battle':'Explore competitive encounters, arena challenges, and combat-themed browser games in the battle collection.','Shooting':'Browse aiming challenges and action-focused shooters. Pick a game, open its page, and step into the action.','Racing':'Discover racing and driving challenges, from fast laps to playful vehicle adventures. Choose your next ride below.','Casual':'Take a lighter break with approachable browser games and playful challenges in the casual collection.','Strategy':'Plan your next move with tactical challenges, defense games, and strategy-focused experiences.','Sports':'Explore the sports collection for ball games, athletic challenges, and quick competitive breaks.','Puzzle':'Browse puzzles and logic challenges for a thoughtful break. Open any title to find its player and related games.','Idle/Clicker':'Find incremental challenges and click-focused browser games. Explore a different pace of play.','Horror':'Browse eerie adventures and unsettling challenges. Content and intensity vary by game; choose what suits you.','Minecraft':'Explore Minecraft-themed and voxel-style experiences in this collection. These games are not affiliated with this website.'}
for g in games:
 title=g['display'];c=g['c'];desc=f'Play {title} free online in the {c} collection. Open the embedded player, switch to fullscreen, and discover more {c.lower()} games on ArcadeWebsite.'
 related=[x for x in games if x['c']==c and x['i']!=g['i']];offset=g['i']%len(related);related=(related[offset:]+related[:offset])[:14]
 breadcrumb=f'<nav class="breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a><span>›</span><a href="{caturl(c)}">{esc(c)}</a><span>›</span><span>{esc(title)}</span></nav>'
 shareurl=quote(BASE+g['url'],safe='');sharetitle=quote('Play '+title,safe='')
 body=breadcrumb+f'<div class="page-head"><a class="tag" href="{caturl(c)}">{esc(c)}</a><h1>{esc(title)}</h1><p>{esc(desc)}</p></div>'+ad('top-leaderboard')+'<div class="play-layout">'+ad('left-sidebar','sidebar')+f'<section class="player-shell" aria-label="Play {esc(title)}"><div class="player-head"><h2>Play {esc(title)}</h2><button data-fullscreen>⛶ Fullscreen</button></div><div class="player"><iframe src="{g["file"]}" title="Play {esc(title)}" allow="fullscreen; gamepad; autoplay" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div><div class="player-note">Click or tap inside the game to begin. Controls vary by title. Press Esc to leave fullscreen.</div></section>'+ad('right-sidebar','sidebar')+'</div>'+ad('below-game')+f'<section class="game-detail"><h2>About {esc(title)}</h2><p>{esc(desc)} The player uses the original game file. Follow any on-screen instructions for controls; keyboard or touch support depends on the game.</p><p>Looking for another challenge? Explore the <a class="tag" href="{caturl(c)}">{esc(c)} collection ↗</a></p><div class="share"><span>Share this game</span><a href="https://www.facebook.com/sharer/sharer.php?u={shareurl}" target="_blank" rel="noopener noreferrer">Facebook ↗</a><a href="https://twitter.com/intent/tweet?url={shareurl}&text={sharetitle}" target="_blank" rel="noopener noreferrer">X ↗</a><button data-copy>Copy link</button><span class="share-status" role="status"></span></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">Keep playing</span><h2>More {esc(c)} games</h2></div><a href="{caturl(c)}">View collection ↗</a></div>'+grid(related,'related-infeed')+'</section>'
 schema={'@context':'https://upload.wikimedia.org/wikipedia/commons/0/0e/Video_game_loot_box_mockup.png?utm_source=en.wikipedia.org&utm_campaign=index&utm_content=original browser','applicationCategory':'Game','isAccessibleForFree':True,'offers':{'@type':'Offer','price':'0','priceCurrency':'USD'}}
 page(g['url'],title+' — Play Free Online | ArcadeWebsite',desc,body,[schema,crumbs([('Home','/'),(c,caturl(c)),(title,g['url'])])],g['image'])
for c in categories:
 name=c['name'];gs=[g for g in games if g['c']==name];intro=catintro[name];path=caturl(name)
 body=f'<nav class="breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a><span>›</span><span>{esc(name)}</span></nav><div class="page-head"><span class="eyebrow">Find your next challenge</span><h1>{esc(name)} games</h1><p>{intro}</p><span class="tag">{len(gs)} games · Free to play</span></div>'+ad('category-leaderboard')+'<section class="section" aria-label="'+esc(name)+' games">'+grid(gs,'category-infeed')+'</section>'
 page(path,name+' Games — Play Free Online | ArcadeWebsite',intro,body,[{'@context':'https://schema.org','@type':'CollectionPage','name':name+' Games','description':intro,'url':BASE+path,'numberOfItems':len(gs)},crumbs([('Home','/'),(name,path)])])
featured=[byid[i] for i in data['featured']];hero_games=[byid[1192],byid[1151],byid[26]]
slides=[{'title':g['t'],'category':g['c'],'image':g['image'],'url':g['url']} for g in hero_games]
g=hero_games[0]
hero=f'<section class="hero" aria-label="Featured games"><img class="hero-art" src="{g["image"]}" alt="{esc(g["t"])} featured game" fetchpriority="high"><div class="hero-copy"><span class="eyebrow" data-hero-category>{esc(g["c"])} / FEATURED PICK</span><h1>Your next<br><span>obsession.</span></h1><p>Big fun. Zero price tag. Jump into <strong data-hero-title>{esc(g["t"])}</strong> and discover a whole world of free arcade games.</p><a class="btn" data-hero-play href="{g["url"]}">▶ Play free now</a><a class="btn secondary" href="/all-games/">Explore games ↗</a></div><div class="hero-controls">'+''.join(f'<button data-slide="{i}" aria-label="Feature {esc(x["title"])}" aria-pressed="{str(i==0).lower()}">0{i+1}</button>' for i,x in enumerate(slides))+'</div></section><script type="application/json" id="hero-data">'+json.dumps(slides).replace('<','\\u003c')+'</script>'
tiles=''.join(f'<a class="category-tile" href="{caturl(c["name"])}"><strong>{esc(c["name"])} ↗</strong><span>{c["count"]} games to discover</span></a>' for c in categories)
body=hero+f'<div class="stats-strip"><span><strong>{len(games):,}</strong> games. Endless possibilities.</span><span><strong>100%</strong> free to explore</span><span>No account needed on ArcadeWebsite</span></div>'+ad('home-leaderboard')+'<div id="featured">'+row('The spotlight',featured,'spotlight','Handpicked favorites. Your next great session starts here.')+'</div>'+row('Trending picks',featured[3:]+featured[:3],'trending','Editorial picks — not a live popularity ranking.')+'<div class="banner"><div><span class="eyebrow">No tickets. No subscription.</span><h2>The arcade is always open.</h2><p>Find something familiar. Discover something unexpected.</p></div><a class="btn" href="/all-games/">Browse all games ↗</a></div>'+row('New to your rotation',list(reversed(featured)),'new','Rediscover the library — not a release-date feed.')+'<section class="section"><div class="section-head"><div><span class="eyebrow">One more round</span><h2>More to discover</h2></div></div>'+grid(featured[:9],'home-infeed')+'</section><section class="section" id="categories"><div class="section-head"><div><span class="eyebrow">Choose your world</span><h2>A game for every mood</h2></div></div><div class="category-grid">'+tiles+'</div></section>'
for c in ['Racing','Puzzle','Platformer','Sports']:
 picks=[g for g in featured if g['c']==c];picks+=[g for g in games if g['c']==c and g not in picks][:10-len(picks)]
 body+=row('Explore '+c,picks,'top-'+slug(c),'A selection from the '+c.lower()+' collection.',caturl(c))
page('/','Free Arcade Games — Find Your Next Obsession | ArcadeWebsite','Discover 1,562 free arcade games. Explore puzzle, racing, action and platform games, each with its own player page. Find your next favorite at ArcadeWebsite.',body)
page('/all-games/','All 1,562 Free Games | ArcadeWebsite','Browse the complete ArcadeWebsite catalog: 1,562 free browser games across 12 categories. Open any game on its own dedicated page.','<div class="page-head"><span class="eyebrow">The complete collection</span><h1>All games. All yours.</h1><p>Explore every game in the library. Thumbnails load as you browse. Use search or category navigation to narrow your next pick.</p><span class="tag">1,562 games · 12 categories</span></div>'+ad('category-leaderboard')+grid(games,'category-infeed'),[{'@context':'https://schema.org','@type':'CollectionPage','name':'All Games','url':BASE+'/all-games/','numberOfItems':len(games)}])
page('/search/','Find a Free Game | ArcadeWebsite','Search the ArcadeWebsite catalog by title or category. Open matching games on their dedicated player pages.','<div class="page-head"><span class="eyebrow">Discover something great</span><h1>Search games</h1><p id="search-term">Find your next game</p></div><p class="results-count" id="result-count" role="status">Loading search…</p><div class="grid" id="search-results"></div><p><a class="btn secondary" href="/all-games/">Browse all games ↗</a></p>',noindex=True)
(OUT/'assets/search-index.json').write_text(json.dumps([{'title':g['display'],'category':g['c'],'url':g['url'],'image':g['image']} for g in games],ensure_ascii=False,separators=(',',':')))
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+esc(u)+'</loc></url>' for u in urls)+'</urlset>')
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nDisallow: /search/\nSitemap: '+BASE+'/sitemap.xml\n')
print(json.dumps({'game_pages':len(games),'categories':len(categories),'indexed_urls':len(urls),'unique_slugs':len(used),'html_pages':len(list(OUT.rglob('*.html')))},indent=2))
